"use client";

/**
 * DropModal — dar de baja una publicación (Mi Garaje, mi-garaje-lab · Mis publicaciones). Misma casa de modales que
 * RepublishModal (.va/.vh): el motivo se elige con un toque (tarjetas 2 × 2 con ícono esmerilado; Input de Concorde para
 * «Otro motivo») y la respuesta cambia según el motivo (si nadie ofertó, se ofrece republicar gratis antes). El botón dice
 * lo que hace y se activa al elegir el motivo; luego «procesando» y cierre. Se monta abierto; para cerrarlo, desmontarlo.
 */
import { useEffect, useId, useRef, useState } from "react";
import type { JSX } from "react";
import Button from "@/concorde/components/Button";
import Input from "@/concorde/components/Input";
import { Vidrio, type Sec } from "@/concorde/components/Vidrio";
import { MODAL_HOUSE_CSS, openFromTouch, REPUBLISH_DAYS } from "@/concorde/components/RepublishModal";

/** Lo propio de DropModal; la tarjeta, el ícono, el título, el botón y las animaciones vienen de MODAL_HOUSE_CSS. */
export const DROP_MODAL_CSS = String.raw`
.dm__why { width: 100%; margin: 20px 0 0; padding: 0; border: 0; }
.dm__why-t { margin: 0 auto 12px; padding: 0; font-size: .875rem; font-weight: 700; color: #3B1782; }
.dm__opts { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
/* Reposo: el borde degradado y la sombra de AmountOption (Concorde) */
.dm__opt { position: relative; display: grid; justify-items: center; align-content: center; gap: 6px; min-height: 88px; padding: 12px 8px; border: 1px solid transparent; border-radius: 16px; cursor: pointer;
  background: linear-gradient(#fff, #fff) padding-box, linear-gradient(335deg, #8460E5 0%, #FFF8F1 100%) border-box; box-shadow: 0 2px 10px rgba(32,0,104,.08);
  font-size: .8125rem; font-weight: 700; line-height: 1.2; color: #3B1782; text-align: center; transition: transform .15s, box-shadow .2s; }
.dm__opt input { position: absolute; opacity: 0; pointer-events: none; }
.dm__opt:hover { box-shadow: 0 4px 16px rgba(32,0,104,.14); }
.dm__opt:active { transform: scale(.98); }
/* Elegido: el borde del Input enfocado de Concorde (naranja → violeta, 2 px) con su brillo naranja y fondo lila */
.dm__opt:has(:checked) { border-width: 2px; background: linear-gradient(#FAF7FF, #FAF7FF) padding-box, linear-gradient(135deg, #ED8936, #8460E5) border-box; box-shadow: 0 0 0 4px rgba(237,137,54,.14); }
.dm__opt:has(:focus-visible) { outline: 2px solid #8460E5; outline-offset: 2px; }
.dm__reply { width: 100%; text-align: left; }
.dm__reply > * { margin-top: 12px; animation: dm-in .25s cubic-bezier(.16,1,.3,1); }
@keyframes dm-in { from { opacity: 0; transform: translateY(-4px); } }
/* Republicar antes de irse: el mismo borde degradado violeta del plazo de RepublishModal */
.dm__save { display: grid; grid-template-columns: auto 1fr; align-items: center; gap: 8px 12px; padding: 12px; border: 1.5px solid transparent; border-radius: 12px;
  background: linear-gradient(#fff, #fff) padding-box, linear-gradient(90deg, #AE8EFF, #5A35C2) border-box; box-shadow: 0 4px 16px rgba(132,96,229,.18); }
.dm__save-ic { display: grid; align-self: start; grid-row: span 2; }
.dm__save-txt { display: grid; gap: 2px; min-width: 0; }
.dm__save-txt b { font-size: .875rem; color: #3B1782; }
.dm__save-txt small { font-size: .75rem; line-height: 1.35; color: #5F5B6B; }
.dm__save-go { grid-column: 2; justify-self: start; min-height: 36px; padding: 0 14px; border: 0; border-radius: 999px; background: linear-gradient(160deg, #8460E5, #3B1782); color: #fff; font-family: inherit; font-size: .8125rem; font-weight: 700; cursor: pointer; }
.dm__save-go:hover { filter: brightness(1.08); }
.dm__save-go:focus-visible { outline: 2px solid #8460E5; outline-offset: 2px; }
/* Respuestas sin acción: la misma tarjeta, en lila suave y sin borde degradado (solo la que tiene botón invita a tocar) */
.dm__info { align-items: center; border: 0; background: #F7F3FF; box-shadow: none; }
.dm__info .dm__save-ic { grid-row: auto; align-self: center; }
.dm__other.pinput-root { width: 100%; }
.dm .vh__btn { margin-top: 20px; }
@media (prefers-reduced-motion: reduce) { .dm__reply > * { animation: none; } }
`;

export const DROP_REASONS = ["Ya lo vendí", "Sin ofertas", "No quiero vender", "Otro motivo"];
const REASON_ICON: Record<string, Sec> = { "Ya lo vendí": "compras", "Sin ofertas": "participaciones", "No quiero vender": "auto", "Otro motivo": "texto" };

export interface DropModalProps {
  /** Nombre del vehículo, p. ej. "Suzuki Swift 2020". */
  name: string;
  /** Foto del vehículo (no se muestra: el modal de la casa no lleva foto). */
  photo?: string;
  /** Lo que dice hoy la fila (no se muestra). */
  note?: string;
  /** Si la publicación se puede republicar: con «Sin ofertas» se ofrece antes de darla de baja. */
  onRepublish?: () => void;
  /** Se llama con el motivo elegido, al terminar el «procesando». */
  onConfirm: (reason: string) => void;
  /** Se llama al cerrar sin dar de baja (×, Escape o clic fuera de la tarjeta). */
  onClose: () => void;
}

/** Respuesta al motivo: misma tarjeta que «Republícala gratis», sin botón (ícono esmerilado, título y una línea). */
const Info = ({ s, t, d }: { s: Sec; t: string; d: string }) => <div className="dm__save dm__info">
  <span className="vd-host dm__save-ic" aria-hidden><Vidrio s={s} size={32} /></span>
  <span className="dm__save-txt"><b>{t}</b><small>{d}</small></span>
</div>;

export function DropModal({ name, onRepublish, onConfirm, onClose }: DropModalProps): JSX.Element {
  const id = useId();
  const ref = useRef<HTMLDialogElement>(null);
  const [reason, setReason] = useState("");
  const [other, setOther] = useState("");
  const [busy, setBusy] = useState(false);
  const finalReason = reason === "Otro motivo" ? other.trim() || "Otro motivo" : reason;
  useEffect(() => openFromTouch(ref.current), []);
  useEffect(() => {
    if (!busy) return;
    const t = setTimeout(() => onConfirm(finalReason), matchMedia("(prefers-reduced-motion: reduce)").matches ? 180 : 650);
    return () => clearTimeout(t);
  }, [busy]); // eslint-disable-line react-hooks/exhaustive-deps
  const close = () => { if (!busy) onClose(); };
  return <>
    <style href="concorde-modal-house" precedence="default">{MODAL_HOUSE_CSS}</style>
    <style href="concorde-drop-modal" precedence="default">{DROP_MODAL_CSS}</style>
    <dialog ref={ref} className="va vh dm" aria-labelledby={`${id}-t`} onCancel={(e) => { e.preventDefault(); close(); }}
    onClick={(e) => { if (e.target === ref.current) close(); }}>
    {busy ? <div className="va__card vh__processing" role="status" aria-live="polite">
      <div className="vh__loader" aria-hidden><i /><i /><i /></div>
      <h2 id={`${id}-t`}>Dando de baja tu auto</h2>
      <p className="vh__sub">Lo estamos quitando de Mis publicaciones…</p>
    </div> : <div className="va__card">
      <button type="button" className="va__x va__x--neg" aria-label="Cerrar" onClick={close} />
      <span className="vd-host vh__icon" aria-hidden><Vidrio s="baja" size={40} /></span>
      <h2 id={`${id}-t`}>Dar de baja</h2>
      <p className="vh__sub">{name}</p>

      {/* Motivos (16/11): 2 × 2 con ícono esmerilado. Recetas de Concorde: borde de AmountOption en reposo y el degradado
          naranja → violeta del Input enfocado al elegir. Radios nativos: flechas y lector de pantalla funcionan solos. */}
      <fieldset className="dm__why">
        <legend className="dm__why-t">¿Por qué la das de baja?</legend>
        <div className="dm__opts">{DROP_REASONS.map((r) => <label key={r} className="vd-host dm__opt">
          <input type="radio" name={`${id}-why`} checked={reason === r} onChange={() => setReason(r)} />
          <Vidrio s={REASON_ICON[r]} size={32} /><span>{r}</span>
        </label>)}</div>
      </fieldset>

      {/* La respuesta cambia con el motivo (aria-live: el lector la anuncia al elegir). */}
      <div className="dm__reply" aria-live="polite">
        {reason === "Sin ofertas" && onRepublish ? <div className="dm__save">
          <span className="vd-host dm__save-ic" aria-hidden><Vidrio s="republicar" size={32} /></span>
          <span className="dm__save-txt"><b>Republícala gratis</b><small>{REPUBLISH_DAYS} días más a la vista.</small></span>
          <button type="button" className="dm__save-go" onClick={onRepublish}>Republicar</button>
        </div> : null}
        {reason === "Ya lo vendí" ? <Info s="compras" t="¡Felicitaciones por la venta!" d="Gracias por contarnos." /> : null}
        {reason === "No quiero vender" ? <Info s="publicar" t="Vuelve cuando quieras" d="Publícalo otra vez desde Mi Garaje." /> : null}
        {reason === "Otro motivo" ? <Input className="dm__other" value={other} onChange={setOther} placeholder="Cuéntanos (opcional)" aria-label="Motivo" /> : null}
      </div>

      <Button type="button" variant="secondary" className="vh__btn" disabled={!reason} onClick={() => setBusy(true)}>Dar de baja</Button>
    </div>}
  </dialog></>;
}

export default DropModal;

// Button.tsx — Generado por Concorde
// Fuente: https://voyager-ds.vercel.app/preview/components/pase1
// Generado: 2026-05-25
// EDITAR LIBREMENTE después de generar

"use client";

import { forwardRef } from "react";
import type { ButtonHTMLAttributes, JSX, ReactNode } from "react";

export type ButtonVariant =
  | "primary"
  | "negotiable"
  | "secondary"
  | "secondary-sm"
  | "ghost"
  | "outline"
  | "sm-guest"
  | "sm-logged-in";

/**
 * Hereda todos los atributos nativos de <button> (type, name, className, style,
 * onMouseEnter, data-*, etc.) — basta con props, no hace falta editar el archivo.
 */
export interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  /** Estilo visual del botón. */
  variant?: ButtonVariant;
  /** Ícono opcional en el slot circular (variantes sm-guest, secondary-sm, sm-logged-in). */
  icon?: ReactNode;
  /** Nombre de usuario — usado cuando variant="sm-logged-in". */
  username?: string;
}

// ── CSS self-contained ────────────────────────────────────────────────────

const BUTTON_STYLES = `
@property --vbtn-angle { syntax: "<angle>"; inherits: false; initial-value: 135deg; }
@property --vbtn-stop-a { syntax: "<color>"; inherits: false; initial-value: oklch(0.72 0.16 55); }
@property --vbtn-stop-b { syntax: "<color>"; inherits: false; initial-value: oklch(0.55 0.22 285); }
@property --vsec-angle { syntax: "<angle>"; inherits: false; initial-value: 160deg; }
@property --vsec-stop-a { syntax: "<color>"; inherits: false; initial-value: oklch(0.38 0.20 285); }
@property --vsec-stop-b { syntax: "<color>"; inherits: false; initial-value: oklch(0.28 0.18 285); }
@property --vneg-angle { syntax: "<angle>"; inherits: false; initial-value: 135deg; }
@property --vneg-stop-a { syntax: "<color>"; inherits: false; initial-value: #00aeb1; }
@property --vneg-stop-b { syntax: "<color>"; inherits: false; initial-value: #8460e5; }
@property --vss-angle { syntax: "<angle>"; inherits: false; initial-value: 160deg; }
@property --vss-stop-a { syntax: "<color>"; inherits: false; initial-value: #8460e5; }
@property --vss-stop-b { syntax: "<color>"; inherits: false; initial-value: #3b1782; }

/* ── primary ─────────────────────────────────────────────────────────── */
.pvbtn {
  --vbtn-stop-a: var(--vmc-color-orange-600, #ed8936);
  --vbtn-stop-b: var(--vmc-color-vault-500, #8460e5);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 48px;
  padding: 0 56px;
  border-radius: var(--vmc-radius-full, 9999px);
  /* Borde GRADIENTE de Figma (1130:1778): white → #FBC47D 25% → #AE8EFF 75% → white */
  border: 2px solid transparent;
  cursor: pointer;
  position: relative;
  overflow: hidden;
  font-family: var(--vmc-font-display, "Plus Jakarta Sans", sans-serif);
  font-size: 16px;
  line-height: 20px;
  font-weight: 600;
  color: var(--vmc-color-base-white, #ffffff);
  text-shadow: rgba(0,0,0,0.25) 0 1px 3px;
  background-image:
    linear-gradient(var(--vbtn-angle), var(--vbtn-stop-a) 0%, var(--vbtn-stop-a) 40%, var(--vbtn-stop-b) 100%),
    linear-gradient(135deg, #ffffff 0%, #fbc47d 25%, #ae8eff 75%, #ffffff 100%);
  background-origin: padding-box, border-box;
  background-clip: padding-box, border-box;
  box-shadow: rgba(255,255,255,0.28) 0 1px 0 2px inset, rgba(237,137,54,0.3) 0 2px 6px;
  transition:
    --vbtn-angle 0.4s cubic-bezier(0.25, 0.8, 0.25, 1),
    --vbtn-stop-a 0.35s,
    --vbtn-stop-b 0.35s,
    transform 0.2s cubic-bezier(0.25, 0.8, 0.25, 1),
    box-shadow 0.25s;
  transform: translateZ(0);
}
.pvbtn::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: var(--vmc-radius-full, 9999px);
  background: linear-gradient(rgba(255,255,255,0.17) 0%, transparent 55%);
  pointer-events: none;
  z-index: 1;
}
.pvbtn::after {
  content: "";
  position: absolute;
  inset: -4px;
  border-radius: var(--vmc-radius-full, 9999px);
  background: linear-gradient(135deg,
    var(--vmc-color-orange-600, oklch(0.72 0.16 55)),
    var(--vmc-color-vault-500, oklch(0.55 0.22 285))
  );
  filter: blur(14px);
  opacity: 0;
  z-index: -1;
  transition: opacity 0.3s, filter 0.3s;
}
.pvbtn:hover {
  --vbtn-angle: 220deg;
  --vbtn-stop-a: var(--vmc-color-orange-400, #fbc47d);
  --vbtn-stop-b: var(--vmc-color-vault-400, #ae8eff);
  transform: translateY(-2px) scale(1.02);
  box-shadow: rgba(255,255,255,0.22) 0 1px 0 2px inset, rgba(132,96,229,0.35) 0 8px 24px, rgba(237,137,54,0.4) 0 4px 10px;
}
.pvbtn:hover::after { opacity: 0.45; filter: blur(18px); }
.pvbtn:active {
  --vbtn-angle: 135deg;
  --vbtn-stop-a: var(--vmc-color-orange-700, #d46e20);
  --vbtn-stop-b: var(--vmc-color-vault-600, #5a35c2);
  color: #d1d5dc;
  transform: scale(0.97) translateY(1px);
  box-shadow: rgba(0,0,0,0.22) 0 2px 5px 2px inset, rgba(0,0,0,0.12) 0 1px 3px;
}
.pvbtn:active::after { opacity: 0; }
.pvbtn:disabled {
  background-image: none;
  background-color: var(--vmc-color-background-disabled, #e1e3e2);
  color: var(--vmc-color-neutral-700, #99a1af);
  text-shadow: none;
  box-shadow: none;
  cursor: not-allowed;
  transform: none;
  border-color: transparent;
}
.pvbtn:disabled::after { display: none; }
.pvbtn:focus-visible {
  outline: transparent solid 3px;
  outline-offset: 4px;
  transform: scale(0.98);
  box-shadow:
    0 0 0 2px var(--vmc-color-base-white, #fff),
    0 0 0 5px var(--vmc-color-vault-500, oklch(0.55 0.22 285)),
    0 8px 16px -4px rgb(51.76% 37.65% 89.8% / 0.30);
}

/* ── secondary ───────────────────────────────────────────────────────── */
.psec {
  --vsec-stop-a: var(--vmc-color-vault-500, #8460e5);
  --vsec-stop-b: var(--vmc-color-vault-700, #3b1782);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 48px;
  padding: 0 56px;
  border-radius: var(--vmc-radius-full, 9999px);
  /* Borde GRADIENTE lila de Figma (1133:2294): #CFBAFF → white 35% → #AE8EFF 65% → #CFBAFF */
  border: 2px solid transparent;
  cursor: pointer;
  position: relative;
  overflow: hidden;
  font-family: var(--vmc-font-display, "Plus Jakarta Sans", sans-serif);
  font-size: 16px;
  line-height: 20px;
  font-weight: 600;
  color: var(--vmc-color-base-white, #ffffff);
  text-shadow: rgba(0,0,0,0.3) 0 1px 3px;
  background-image:
    linear-gradient(var(--vsec-angle), var(--vsec-stop-a) 0%, var(--vsec-stop-b) 100%),
    linear-gradient(135deg, #cfbaff 0%, #ffffff 35%, #ae8eff 65%, #cfbaff 100%);
  background-origin: padding-box, border-box;
  background-clip: padding-box, border-box;
  box-shadow: rgba(255,255,255,0.22) 0 1px 0 2px inset, rgba(132,96,229,0.3) 0 2px 8px;
  transition:
    --vsec-angle 0.4s cubic-bezier(0.25, 0.8, 0.25, 1),
    --vsec-stop-a 0.35s,
    --vsec-stop-b 0.35s,
    transform 0.2s cubic-bezier(0.25, 0.8, 0.25, 1),
    box-shadow 0.25s;
  transform: translateZ(0);
}
.psec::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: var(--vmc-radius-full, 9999px);
  background: linear-gradient(rgba(255,255,255,0.15) 0%, transparent 55%);
  pointer-events: none;
  z-index: 1;
}
.psec::after {
  content: "";
  position: absolute;
  inset: -4px;
  border-radius: var(--vmc-radius-full, 9999px);
  background: linear-gradient(135deg,
    var(--vmc-color-vault-500, oklch(0.55 0.22 285)),
    var(--vmc-color-vault-700, oklch(0.38 0.20 285))
  );
  filter: blur(14px);
  opacity: 0;
  z-index: -1;
  transition: opacity 0.3s, filter 0.3s;
}
.psec:hover {
  --vsec-angle: 219deg;
  --vsec-stop-a: var(--vmc-color-vault-400, #ae8eff);
  --vsec-stop-b: var(--vmc-color-vault-600, #5a35c2);
  transform: translateY(-2px) scale(1.02);
  box-shadow: rgba(255,255,255,0.2) 0 1px 0 2px inset, rgba(132,96,229,0.4) 0 8px 24px, rgba(132,96,229,0.25) 0 4px 10px;
}
.psec:hover::after { opacity: 0.45; filter: blur(18px); }
.psec:active {
  --vsec-angle: 160deg;
  --vsec-stop-a: var(--vmc-color-vault-700, #3b1782);
  --vsec-stop-b: var(--vmc-color-vault-900, #22005c);
  color: #d1d5dc;
  transform: scale(0.97) translateY(1px);
  box-shadow: rgba(0,0,0,0.28) 0 2px 5px 2px inset, rgba(0,0,0,0.14) 0 1px 3px;
}
.psec:active::after { opacity: 0; }
.psec:disabled {
  background-image: none;
  background-color: var(--vmc-color-background-disabled, #e1e3e2);
  color: var(--vmc-color-neutral-700, #99a1af);
  text-shadow: none;
  box-shadow: none;
  cursor: not-allowed;
  transform: none;
  border-color: transparent;
}
.psec:disabled::after { display: none; }
.psec:focus-visible {
  outline: transparent solid 3px;
  outline-offset: 4px;
  transform: scale(0.98);
  box-shadow:
    0 0 0 2px var(--vmc-color-base-white, #fff),
    0 0 0 5px var(--vmc-color-vault-500, oklch(0.55 0.22 285)),
    0 8px 16px -4px rgb(51.76% 37.65% 89.8% / 0.30);
}

/* ── ghost · "Ver Ofertas relacionadas" ─────────────────────────────────
   Sync SVG Figma (1143:1709/1885/1909): frame 215×48 con texto casi al
   borde → padding 12px (antes 28px). Estados ya coincidían exacto. */
.pghost {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 48px;
  padding: 0 12px;
  border-radius: var(--vmc-radius-full, 9999px);
  border: 2px solid rgba(255,255,255,0.75);
  cursor: pointer;
  position: relative;
  overflow: hidden;
  font-family: var(--vmc-font-display, "Plus Jakarta Sans", sans-serif);
  font-size: 16px;
  line-height: 20px;
  font-weight: 600;
  color: var(--vmc-color-base-white, #ffffff);
  background: transparent;
  text-shadow: rgba(0,0,0,0.18) 0 1px 3px;
  box-shadow: rgba(255,255,255,0.2) 0 1px 0 2px inset, rgba(255,255,255,0.15) 0 0 0 1px;
  transition:
    background 0.25s,
    border-color 0.25s,
    color 0.25s,
    transform 0.2s cubic-bezier(0.25, 0.8, 0.25, 1),
    box-shadow 0.25s;
  transform: translateZ(0);
}
.pghost::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: var(--vmc-radius-full, 9999px);
  background: linear-gradient(rgba(255,255,255,0.1) 0%, transparent 55%);
  pointer-events: none;
  z-index: 1;
}
.pghost::after {
  content: "";
  position: absolute;
  inset: -4px;
  border-radius: var(--vmc-radius-full, 9999px);
  background: linear-gradient(135deg,
    var(--vmc-color-orange-600, oklch(0.72 0.16 55)),
    var(--vmc-color-vault-500, oklch(0.55 0.22 285))
  );
  filter: blur(16px);
  opacity: 0;
  z-index: -1;
  transition: opacity 0.3s, filter 0.3s;
}
.pghost:hover {
  background: linear-gradient(146.64deg, #fff 0%, rgb(255,240,226) 100%);
  border-color: #fff;
  color: #ed8936;
  text-shadow: rgba(0,0,0,0.25) 0 1px 3px;
  transform: translateY(-2px) scale(1.02);
  box-shadow: rgba(255,255,255,0.5) 0 1px 0 2px inset, rgba(0,0,0,0.2) 0 6px 20px;
}
.pghost:hover::after { opacity: 0.4; filter: blur(18px); }
.pghost:active {
  background: linear-gradient(146.56deg, rgb(212,110,32) 0%, rgb(183,55,0) 100%);
  border-color: #d46e20;
  color: var(--vmc-color-icon-disabled, #e1e3e2);
  text-shadow: rgba(0,0,0,0.25) 0 1px 3px;
  transform: scale(0.97) translateY(1px);
  box-shadow: rgba(0,0,0,0.22) 0 2px 5px 2px inset;
}
.pghost:active::after { opacity: 0; }
.pghost:disabled {
